import { defineConfig } from 'astro/config';
import { appendFileSync, cpSync, existsSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

// Field trip addresses start with a permanent ID ("t42-..."). The rest of the address follows
// the trip's name and date, so it can change. This adds a redirect for each trip so older links
// still land on the right page. The lines are generated by src/pages/trip-redirects.txt.ts and
// appended to any hand-written rules in public/_redirects.
const tripRedirects = {
  name: 'trip-redirects',
  hooks: {
    'astro:build:done': ({ dir }) => {
      const out = fileURLToPath(dir);

      // Images copied from Notion during the build (see src/lib/notion-images.ts).
      if (existsSync('.trip-images')) cpSync('.trip-images', `${out}trip-images`, { recursive: true });

      const generated = `${out}trip-redirects.txt`;
      if (!existsSync(generated)) return;
      const lines = readFileSync(generated, 'utf8');
      const target = `${out}_redirects`;
      if (existsSync(target)) appendFileSync(target, `\n${lines}`);
      else writeFileSync(target, lines);
      rmSync(generated);
    },
  },
};

export default defineConfig({
  site: 'https://nwarkaudubon.org',
  integrations: [tripRedirects],
  // Astro's HTML compression drops the space when a line break comes right before an inline
  // element (e.g. "email\n<a href>" renders as "email<a href>"). Turning it off lets us wrap
  // source lines freely. The size cost is negligible.
  compressHTML: false,
});
